import { Module } from '@nestjs/common';
import { PassportModule } from '@nestjs/passport';
import { JwtModule } from '@nestjs/jwt';
import { TypeOrmModule } from '@nestjs/typeorm';
import { ConfigService } from '@nestjs/config';
import { AuthController } from './auth.controller';
import { IdentityController } from './controllers/identity.controller';
import { AuthService } from './auth.service';
import { Web3AuthVerifierService } from './services/web3auth-verifier.service';
import { TokenService } from './services/token.service';
import { JwtIssuerService } from './services/jwt-issuer.service';
import { GoogleOAuthService } from './services/google-oauth.service';
import { EmailOtpService } from './services/email-otp.service';
import { SiweService } from './services/siwe.service';
import { JwtStrategy } from './strategies/jwt.strategy';
import { User } from './entities/user.entity';
import { RefreshToken } from './entities/refresh-token.entity';
import { AuthMethod } from './entities/auth-method.entity';
import { PinnedCid } from '../vault/entities/pinned-cid.entity';
import { IpfsModule } from '../ipfs/ipfs.module';

@Module({
  imports: [
    PassportModule.register({ defaultStrategy: 'jwt' }),
    JwtModule.registerAsync({
      useFactory: (configService: ConfigService) => ({
        secret: configService.get<string>('JWT_SECRET'),
        signOptions: { expiresIn: '15m' },
      }),
      inject: [ConfigService],
    }),
    TypeOrmModule.forFeature([User, RefreshToken, AuthMethod, PinnedCid]),
    IpfsModule.forRootAsync(),
  ],
  controllers: [AuthController, IdentityController],
  providers: [
    AuthService,
    Web3AuthVerifierService,
    TokenService,
    JwtIssuerService,
    GoogleOAuthService,
    EmailOtpService,
    SiweService,
    JwtStrategy,
  ],
  exports: [AuthService, JwtModule],
})
export class AuthModule {}

