  2→import { getRepositoryToken } from '@nestjs/typeorm';
  3→import { JwtService } from '@nestjs/jwt';
  4→import { UnauthorizedException } from '@nestjs/common';
  5→import * as argon2 from 'argon2';
  6→import { TokenService } from './token.service';
  7→import { RefreshToken } from '../entities/refresh-token.entity';
  8→
  9→describe('TokenService', () => {
 10→  let service: TokenService;
 11→  let jwtService: jest.Mocked<JwtService>;
 12→  let refreshTokenRepo: jest.Mocked<Record<string, jest.Mock>>;
 13→
 14→  beforeEach(async () => {
 15→    const mockJwtService = {
 16→      sign: jest.fn().mockReturnValue('mock-jwt-access-token'),
 17→    };
 18→
 19→    const mockRefreshTokenRepo = {
 20→      find: jest.fn(),
 21→      save: jest.fn(),
 22→      update: jest.fn(),
 23→    };
 24→
 25→    const module: TestingModule = await Test.createTestingModule({
 26→      providers: [
 27→        TokenService,
 28→        { provide: JwtService, useValue: mockJwtService },
 29→        { provide: getRepositoryToken(RefreshToken), useValue: mockRefreshTokenRepo },
 30→      ],
 31→    }).compile();
 32→
 33→    service = module.get<TokenService>(TokenService);
 34→    jwtService = module.get(JwtService);
 35→    refreshTokenRepo = module.get(getRepositoryToken(RefreshToken));
 36→  });
 37→
 38→  afterEach(() => {
 39→    jest.resetAllMocks();
 40→  });
 41→
 42→  describe('createTokens', () => {
 43→    it('should generate access token with correct payload', async () => {
 44→      refreshTokenRepo.save.mockResolvedValue({
 45→        id: 'token-id',
 46→        userId: 'user-123',
 47→        tokenHash: 'hashed',
 48→        expiresAt: new Date(),
 49→      });
