 54→        { sub: 'user-123', publicKey: 'public-key-abc' },
 55→        { expiresIn: '15m' }
 56→      );
 57→    });
 58→
 59→    it('should generate random refresh token and hash with argon2', async () => {
 60→      refreshTokenRepo.save.mockResolvedValue({
 61→        id: 'token-id',
 62→        userId: 'user-123',
