  let authMethodRepository: Record<string, jest.Mock>;
  let refreshTokenRepository: Record<string, jest.Mock>;
  let pinnedCidRepository: Record<string, jest.Mock>;
  let ipfsProvider: Record<string, jest.Mock>;

