  1→import { useCallback, useEffect, useState } from 'react';
  2→import { useNavigate, useLocation } from 'react-router-dom';
  3→import { StatusIndicator } from '../components/layout';
  4→import { GoogleLoginButton } from '../components/auth/GoogleLoginButton';
  5→import { EmailLoginForm } from '../components/auth/EmailLoginForm';
  6→import { WalletLoginButton } from '../components/auth/WalletLoginButton';
  7→import { DeviceWaitingScreen } from '../components/mfa/DeviceWaitingScreen';
  8→import { RecoveryInput } from '../components/mfa/RecoveryInput';
  9→import { MatrixBackground } from '../components/MatrixBackground';
 10→import { StagingBanner } from '../components/StagingBanner';
 11→import { useHealthControllerCheck } from '../api/health/health';
 12→import { useAuth } from '../hooks/useAuth';
 13→
 14→type MfaView = 'waiting' | 'recovery';
 15→
 16→/**
 17→ * Login page with terminal aesthetic and matrix background.
 18→ * CipherBox-branded custom login UI with Google OAuth and email OTP.
 19→ *
 20→ * When REQUIRED_SHARE is detected (MFA enabled, new device), switches
 21→ * to either DeviceWaitingScreen or RecoveryInput instead of the login form.
 22→ */
 23→export function Login() {
 24→  const {
 25→    isAuthenticated,
 26→    isLoading,
 27→    isRequiredShare,
 28→    completeRequiredShare,
 29→    loginWithGoogle,
 30→    loginWithEmail,
 31→    loginWithWallet,
 32→  } = useAuth();
 33→  const navigate = useNavigate();
 34→  const location = useLocation();
 35→  const [loginError, setLoginError] = useState<string | null>(null);
 36→  const [mfaView, setMfaView] = useState<MfaView>('waiting');
 37→
 38→  // Health check for disabling connect button when API is down
 39→  const {
 40→    data: healthData,
 41→    isLoading: isHealthLoading,
 42→    isError: isHealthError,
 43→  } = useHealthControllerCheck({
 44→    query: {
 45→      refetchInterval: 30000,
 46→      retry: 2,
 47→      refetchOnWindowFocus: true,
 48→    },
 49→  });
 50→
 51→  const isApiDown = !isHealthLoading && (isHealthError || healthData?.status !== 'ok');
 52→
 53→  // Redirect if already authenticated AND still on the login page.
 54→  // The pathname check prevents a late-firing re-render (e.g. from
 55→  // setIsLoggingIn(false) in the login finally block) from navigating
 56→  // to /files after the user has already moved to a different route.
 57→  // The isRequiredShare check prevents redirecting when the user has a
 58→  // temp access token but still needs to complete MFA (device approval
 59→  // or recovery phrase). Without this, the redirect would unmount
 60→  // DeviceWaitingScreen before the approval request is created.
 61→  useEffect(() => {
 62→    if (isAuthenticated && !isRequiredShare && location.pathname === '/') {
 63→      navigate('/files');
 64→    }
 65→  }, [isAuthenticated, isRequiredShare, location.pathname, navigate]);
 66→
 67→  const handleGoogleLogin = useCallback(
 68→    async (googleIdToken: string) => {
 69→      setLoginError(null);
 70→      try {
 71→        await loginWithGoogle(googleIdToken);
 72→      } catch (err) {
 73→        setLoginError(err instanceof Error ? err.message : 'Google login failed');
 74→      }
 75→    },
 76→    [loginWithGoogle]
 77→  );
 78→
 79→  const handleEmailLogin = useCallback(
 80→    async (email: string, otp: string) => {
 81→      setLoginError(null);
 82→      try {
 83→        await loginWithEmail(email, otp);
 84→      } catch (err) {
 85→        setLoginError(err instanceof Error ? err.message : 'Email login failed');
 86→      }
 87→    },
 88→    [loginWithEmail]
 89→  );
 90→
 91→  const handleWalletLogin = useCallback(
 92→    async (idToken: string, userId: string) => {
 93→      setLoginError(null);
 94→      try {
 95→        await loginWithWallet(idToken, userId);
 96→      } catch (err) {
 97→        setLoginError(err instanceof Error ? err.message : 'Wallet login failed');
 98→      }
 99→    },
100→    [loginWithWallet]
101→  );
102→
103→  const handleRecoveryFallback = useCallback(() => {
104→    setMfaView('recovery');
105→  }, []);
106→
107→  const handleBackToWaiting = useCallback(() => {
108→    setMfaView('waiting');
109→  }, []);
110→
111→  const handleRecoveryComplete = useCallback(async () => {
112→    // Recovery succeeded: Core Kit is now LOGGED_IN.
113→    // completeRequiredShare() will do backend auth + vault load + navigate.
114→    try {
115→      await completeRequiredShare();
116→    } catch (err) {
117→      setLoginError(err instanceof Error ? err.message : 'Failed to complete login after recovery');
118→    }
119→  }, [completeRequiredShare]);
120→
121→  const handleApprovalComplete = useCallback(() => {
122→    // Approval flow already called completeRequiredShare() inside the hook.
123→    // If it failed, the hook sets approvalError which DeviceWaitingScreen renders.
124→    // Nothing extra needed here -- navigation happens in completeRequiredShare.
125→  }, []);
126→
127→  // Show loading state while checking authentication
128→  if (isLoading) {
129→    return (
130→      <>
131→        <StagingBanner variant="login" />
132→        <div className="login-container">
133→          <MatrixBackground opacity={0.3} frameInterval={50} />
134→          <div className="loading">initializing...</div>
135→          <LoginFooter />
136→        </div>
137→      </>
138→    );
139→  }
140→
141→  // REQUIRED_SHARE state: show MFA challenge UI instead of login form
142→  if (isRequiredShare) {
143→    return (
144→      <>
145→        <StagingBanner variant="login" />
146→        <div className="login-container">
147→          <MatrixBackground opacity={0.3} frameInterval={50} />
148→          {mfaView === 'waiting' ? (
149→            <DeviceWaitingScreen
150→              onRecoveryFallback={handleRecoveryFallback}
151→              onApprovalComplete={handleApprovalComplete}
152→            />
153→          ) : (
154→            <RecoveryInput
155→              onRecoveryComplete={handleRecoveryComplete}
156→              onBack={handleBackToWaiting}
157→            />
158→          )}
159→          {loginError && (
160→            <div className="login-error" role="alert" aria-live="polite">
161→              {loginError}
162→            </div>
163→          )}
164→          <LoginFooter />
165→        </div>
166→      </>
167→    );
168→  }
169→
170→  return (
171→    <>
172→      <StagingBanner variant="login" />
173→      <div className="login-container">
174→        <MatrixBackground opacity={0.3} frameInterval={50} />
175→        <div className="login-panel">
176→          <h1>CIPHERBOX</h1>
177→          <p className="tagline">zero-knowledge encrypted storage</p>
178→          <p className="login-description">
179→            your files, encrypted on your device. we never see your data.
180→          </p>
181→
182→          <div className="login-methods">
183→            <GoogleLoginButton onLogin={handleGoogleLogin} disabled={isLoading || isApiDown} />
184→
185→            <div className="login-divider">
186→              <span>{'// or'}</span>
187→            </div>
188→
189→            <EmailLoginForm onLogin={handleEmailLogin} disabled={isLoading || isApiDown} />
190→
191→            <div className="login-divider">
192→              <span>{'// or'}</span>
193→            </div>
194→
195→            <WalletLoginButton onLogin={handleWalletLogin} disabled={isLoading || isApiDown} />
196→          </div>
197→
198→          {loginError && (
199→            <div className="login-error" role="alert" aria-live="polite">
200→              {loginError}
201→            </div>
202→          )}
203→        </div>
204→        <LoginFooter />
205→      </div>
206→    </>
207→  );
208→}
209→
210→/** Shared footer to avoid duplication across login states. */
211→function LoginFooter() {
212→  return (
